import asyncio, datetime
from playwright.async_api import async_playwright
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch(executable_path='/usr/bin/google-chrome',args=['--no-sandbox'])
        pg=await (await b.new_context(viewport={'width':1700,'height':900},accept_downloads=True)).new_page(); errs=[]; pg.on('pageerror',lambda e:errs.append(str(e)))
        await pg.goto('http://localhost:8765/index.html'); await pg.wait_for_timeout(1500)
        await pg.fill('#name','David'); await pg.fill('#country','Kenya'); await pg.fill('#key','k'); await pg.click('text=Start'); await pg.wait_for_timeout(400)
        await pg.evaluate("S.skin='ultraviolet';applyTheme();S.plans.push({id:'pb',name:'Building new site office',what:'x',custom:true,started:Date.now(),acts:[{name:'Survey',status:'todo',owner:'Wanjiru Kamau'},{name:'Permit',status:'doing',owner:'wanjiru kamau'}],log:[]});S.brief={day:dash(Date.now()),at:Date.now(),summary:'x',pri:[],ai:false};save();render()")
        await pg.click('nav [data-v=settings]'); print('top tabs',await pg.locator('.settop button').all_inner_texts()); await pg.click('.settop [data-v=resources]'); await pg.wait_for_timeout(200)
        print('empty state sections',await pg.locator('.page section.card').count(),'| sidebar current',await pg.locator('nav [aria-current=page]').inner_text(),'| back',await pg.locator('main [data-act=back]').count())
        await pg.click('[data-act=res-new][data-v=person]'); await pg.fill('#rname','Wanjiru Kamau'); await pg.fill('#rrole','Site engineer'); await pg.fill('#rhours','40'); await pg.fill('#rrate','4,500'); await pg.select_option('#rpid','pb'); await pg.screenshot(path='rs-modal.png'); await pg.click('[data-x=save]'); await pg.wait_for_timeout(150)
        await pg.click('[data-act=res-new][data-v=person]'); await pg.fill('#rname','Otieno Odhiambo'); await pg.fill('#rrole','Foreman'); await pg.select_option('#ravail','part'); await pg.fill('#rrate','60000'); await pg.select_option('#runit','month'); await pg.click('[data-x=save]'); await pg.wait_for_timeout(150)
        await pg.click('[data-act=res-new][data-v=person]'); await pg.fill('#rname','Jane Consultant'); await pg.select_option('#ravail','no'); await pg.fill('#rrate','100'); await pg.select_option('#runit','hour'); await pg.select_option('#rcur','USD'); await pg.click('[data-x=save]'); await pg.wait_for_timeout(150)
        soon=(datetime.date.today()+datetime.timedelta(days=5)).isoformat()
        await pg.click('[data-act=res-new][data-v=equipment]'); await pg.fill('#rname','Excavator'); await pg.fill('#rcap','20 t'); await pg.select_option('#rown','hired'); await pg.fill('#rrate','35000'); await pg.fill('#rservice',soon); await pg.click('[data-x=save]'); await pg.wait_for_timeout(150)
        await pg.click('[data-act=res-new][data-v=other]'); await pg.fill('#rname','Cement, 50 kg bags'); await pg.fill('#rcat','Materials'); await pg.fill('#rqty','120'); await pg.select_option('#runit','bag'); await pg.fill('#rrate','850'); await pg.fill('#rsupplier','Bamburi'); await pg.click('[data-x=save]'); await pg.wait_for_timeout(200)
        print('tiles:',[x.replace('\n',' | ') for x in await pg.locator('.btile').all_inner_texts()])
        print('people rows:',[ (await x.inner_text()).replace('\n',' ').replace('\t',' | ') for x in await pg.locator('table.rt >> nth=0 >> tbody tr').all()])
        print('equipment row:',(await pg.locator('table.rt >> nth=1 >> tbody tr').inner_text()).replace('\n',' ').replace('\t',' | ')); print('other row:',(await pg.locator('table.rt >> nth=2 >> tbody tr').inner_text()).replace('\n',' ').replace('\t',' | '))
        await pg.screenshot(path='rs-page.png',full_page=False)
        await pg.click('.page .htabs [data-v=equipment]'); await pg.wait_for_timeout(150); print('filter equipment -> tables',await pg.locator('table.rt').count()); await pg.click('.page .htabs [data-v=all]')
        async with pg.expect_download() as dl: await pg.click('[data-act=res-csv]')
        d=await dl.value; txt=open(await d.path(),encoding='utf-8-sig').read(); print('CSV',d.suggested_filename,'rows',len(txt.splitlines()),'| has Wanjiru & excavator','Wanjiru Kamau' in txt and 'Excavator' in txt)
        await pg.click('[data-act=res-open] >> nth=0'); await pg.fill('#rrate','5000'); await pg.click('[data-x=save]'); await pg.wait_for_timeout(150); print('edit saved:',await pg.evaluate("S.resources[0].rate"))
        await pg.click('[data-act=res-tasks]'); await pg.wait_for_timeout(200); print('open tasks link -> view',await pg.evaluate("[V.view,V.towner]"),'cards',await pg.locator('.kcard').count())
        await pg.click('.toolbar [data-act=task-new]'); print('owner suggestions include staff:',await pg.evaluate("[...document.querySelectorAll('#ownerlist option')].map(o=>o.value)")); await pg.click('[data-x=cancel]')
        print('assistant context has resources:',await pg.evaluate("dataContext('who is available').resources.length"))
        await pg.reload(); await pg.wait_for_timeout(1500); print('after reload',await pg.evaluate("S.resources.length"))
        await pg.set_viewport_size({'width':390,'height':800}); await pg.evaluate("V.view='resources';render()"); await pg.wait_for_timeout(200); print('phone overflow-x',await pg.evaluate('document.documentElement.scrollWidth>innerWidth'),'errors',errs)
        await b.close()
asyncio.run(main())
